<?php
class Livestock extends Model
{
 protected $table='livestock_batches';
 public function references(){return['species'=>$this->query("SELECT * FROM livestock_species WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll(),'facilities'=>$this->scoped("SELECT * FROM livestock_facilities WHERE status='active' AND deleted_at IS NULL",'site_id'),'feed_products'=>$this->query("SELECT id,code,name FROM products WHERE code='ALIMENT-BETAIL' AND deleted_at IS NULL")->fetchAll()];}
 public function batches(){$p=[];$s=Auth::siteClause('b.site_id',$p);return$this->query("SELECT b.*,sp.name species_name,sp.category,f.name facility_name,f.facility_type,f.area_m2,COALESCE((SELECT SUM(quantity_kg) FROM livestock_feedings WHERE batch_id=b.id AND deleted_at IS NULL),0) feed_kg,COALESCE((SELECT SUM(eggs_count) FROM poultry_productions WHERE batch_id=b.id),0) eggs_count FROM livestock_batches b JOIN livestock_species sp ON sp.id=b.species_id JOIN livestock_facilities f ON f.id=b.facility_id WHERE b.deleted_at IS NULL{$s} ORDER BY b.id DESC",$p)->fetchAll();}
 public function conversions(){$p=[];$s=Auth::siteClause('b.site_id',$p);return$this->query("SELECT c.*,b.batch_number,sp.name species_name,ws.id stock_id,ws.quantity_kg,ws.reserved_kg FROM livestock_conversions c JOIN livestock_batches b ON b.id=c.batch_id JOIN livestock_species sp ON sp.id=b.species_id LEFT JOIN livestock_weight_stocks ws ON ws.conversion_id=c.id WHERE 1=1{$s} ORDER BY c.id DESC",$p)->fetchAll();}
 public function transfers(){$p=[];$s=Auth::siteClause('t.source_site_id',$p);return$this->query("SELECT t.*,b.batch_number,d.document_number FROM livestock_transfers t JOIN livestock_batches b ON b.id=t.batch_id LEFT JOIN documents d ON d.entity_type='livestock_transfers' AND d.entity_id=t.id AND d.document_type_id=(SELECT id FROM document_types WHERE code='BTR') WHERE t.deleted_at IS NULL{$s} ORDER BY t.id DESC",$p)->fetchAll();}
 public function createFacility(array$d){$site=$this->farm();$area=$d['facility_type']==='pond'?(float)$d['area_m2']:null;if($d['facility_type']==='pond'&&$area<=0)throw new RuntimeException('Surface de l’étang obligatoire.');$this->query("INSERT INTO livestock_facilities(site_id,code,name,facility_type,area_m2,capacity_heads,status) VALUES(:site,:code,:name,:type,:area,:capacity,'active')",['site'=>$site,'code'=>trim($d['code']),'name'=>trim($d['name']),'type'=>$d['facility_type'],'area'=>$area,'capacity'=>$d['capacity_heads']?:null]);return(int)$this->db->lastInsertId();}
 public function createBatch(array$d,array$u){$site=$this->farm();$f=$this->row('SELECT * FROM livestock_facilities WHERE id=? AND site_id=? AND deleted_at IS NULL',[$d['facility_id'],$site]);$sp=$this->row('SELECT * FROM livestock_species WHERE id=? AND deleted_at IS NULL',[$d['species_id']]);$heads=(int)$d['initial_heads'];if(!$f||!$sp||$heads<=0)throw new RuntimeException('Lot d’élevage invalide.');if($sp['category']==='fish'&&$f['facility_type']!=='pond')throw new RuntimeException('Un lot piscicole exige un étang.');if($sp['category']==='poultry'&&$f['facility_type']!=='poultry_house')throw new RuntimeException('Un lot avicole exige un poulailler.');$n='ELV-'.date('YmdHis').'-'.random_int(100,999);$this->db->beginTransaction();try{$this->query("INSERT INTO livestock_batches(site_id,species_id,facility_id,batch_number,purpose,started_at,initial_heads,current_heads,initial_average_weight_kg,current_average_weight_kg,status,created_by) VALUES(:site,:species,:facility,:number,:purpose,:start,:heads,:current,:weight,:weight2,'active',:user)",['site'=>$site,'species'=>$sp['id'],'facility'=>$f['id'],'number'=>$n,'purpose'=>$d['purpose'],'start'=>$d['started_at'],'heads'=>$heads,'current'=>$heads,'weight'=>$d['initial_average_weight_kg']?:null,'weight2'=>$d['initial_average_weight_kg']?:null,'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$this->headMove($id,'stocking',$heads,0,$heads,'livestock_batches',$id,$u);if($sp['category']==='fish')$this->query('INSERT INTO fish_stockings(batch_id,stocked_heads,total_weight_kg,stocked_at,created_by) VALUES(:batch,:heads,:weight,NOW(),:user)',['batch'=>$id,'heads'=>$heads,'weight'=>$d['initial_total_weight_kg']?:null,'user'=>$u['id']]);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function feed(array$d,array$u){$b=$this->batch($d['batch_id']);$q=(float)$d['quantity_kg'];if($q<=0)throw new RuntimeException('Quantité d’aliment invalide.');$this->query('INSERT INTO livestock_feedings(batch_id,feed_product_id,quantity_kg,fed_at,unit_cost,created_by) VALUES(:batch,:product,:qty,:at,:cost,:user)',['batch'=>$b['id'],'product'=>$d['feed_product_id']?:null,'qty'=>$q,'at'=>$d['fed_at'],'cost'=>(float)$d['unit_cost'],'user'=>$u['id']]);}
 public function weigh(array$d,array$u){$b=$this->batch($d['batch_id']);$heads=(int)$d['sample_heads'];$kg=(float)$d['total_weight_kg'];if($heads<=0||$heads>(int)$b['current_heads']||$kg<=0)throw new RuntimeException('Pesée invalide.');$avg=$kg/$heads;$this->query('INSERT INTO livestock_weighings(batch_id,sample_heads,total_weight_kg,average_weight_kg,weighed_at,created_by) VALUES(:batch,:heads,:kg,:avg,:at,:user)',['batch'=>$b['id'],'heads'=>$heads,'kg'=>$kg,'avg'=>$avg,'at'=>$d['weighed_at'],'user'=>$u['id']]);$this->query('UPDATE livestock_batches SET current_average_weight_kg=:avg WHERE id=:id',['avg'=>$avg,'id'=>$b['id']]);return$avg;}
 public function poultry(array$d,array$u){$b=$this->batch($d['batch_id'],true);if($b['category']!=='poultry')throw new RuntimeException('Lot non avicole.');$mort=(int)$d['mortality_heads'];$sold=(int)$d['sold_heads'];$out=$mort+$sold;if($out<0||$out>(int)$b['current_heads'])throw new RuntimeException('Sortie avicole supérieure à l’effectif.');$this->db->beginTransaction();try{$this->query('INSERT INTO poultry_productions(batch_id,production_date,eggs_count,mortality_heads,sold_heads,created_by) VALUES(:batch,:date,:eggs,:mortality,:sold,:user)',['batch'=>$b['id'],'date'=>$d['production_date'],'eggs'=>(int)$d['eggs_count'],'mortality'=>$mort,'sold'=>$sold,'user'=>$u['id']]);$ref=(int)$this->db->lastInsertId();$before=(int)$b['current_heads'];if($mort)$this->headMove($b['id'],'mortality',$mort,$before,$before-$mort,'poultry_productions',$ref,$u);if($sold)$this->headMove($b['id'],'sale',$sold,$before-$mort,$before-$out,'poultry_productions',$ref,$u);$this->query('UPDATE livestock_batches SET current_heads=:heads WHERE id=:id',['heads'=>$before-$out,'id'=>$b['id']]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createConversion(array$d,array$u){$b=$this->batch($d['batch_id'],true);$heads=(int)$d['input_heads'];$gross=(float)$d['gross_weight_kg'];$tare=(float)$d['tare_weight_kg'];$net=$gross-$tare;if($heads<=0||$heads>(int)$b['current_heads']||$gross<=0||$tare<0||$net<=0)throw new RuntimeException('Conversion/pesée invalide.');$n='CONV-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO livestock_conversions(batch_id,conversion_number,conversion_type,input_heads,gross_weight_kg,tare_weight_kg,net_weight_kg,converted_at,status,created_by) VALUES(:batch,:number,:type,:heads,:gross,:tare,:net,:at,'submitted',:user)",['batch'=>$b['id'],'number'=>$n,'type'=>$d['conversion_type'],'heads'=>$heads,'gross'=>$gross,'tare'=>$tare,'net'=>$net,'at'=>$d['converted_at'],'user'=>$u['id']]);return(int)$this->db->lastInsertId();}
 public function createFishCatch(array$d,array$u){$b=$this->batch($d['batch_id'],true);if($b['category']!=='fish'||(float)$b['area_m2']<=0)throw new RuntimeException('Lot piscicole ou surface d’étang invalide.');$d['conversion_type']='fish_catch';$conversion=$this->createConversion($d,$u);$net=(float)$d['gross_weight_kg']-(float)$d['tare_weight_kg'];$this->query("INSERT INTO fish_catches(batch_id,conversion_id,catch_number,heads_caught,gross_weight_kg,tare_weight_kg,net_weight_kg,yield_kg_m2,status,caught_at,created_by) VALUES(:batch,:conversion,:number,:heads,:gross,:tare,:net,:yield,'submitted',:at,:user)",['batch'=>$b['id'],'conversion'=>$conversion,'number'=>'PEC-'.date('YmdHis').'-'.random_int(100,999),'heads'=>(int)$d['input_heads'],'gross'=>$d['gross_weight_kg'],'tare'=>$d['tare_weight_kg'],'net'=>$net,'yield'=>$net/(float)$b['area_m2'],'at'=>$d['converted_at'],'user'=>$u['id']]);return$conversion;}
 public function validateConversion($id,array$u){$this->db->beginTransaction();try{$c=$this->row('SELECT c.*,b.site_id,b.current_heads FROM livestock_conversions c JOIN livestock_batches b ON b.id=c.batch_id WHERE c.id=? FOR UPDATE',[$id]);if(!$c||$c['status']!=='submitted')throw new RuntimeException('Conversion non validable ou déjà validée.');Auth::requireSiteAccess($c['site_id']);if((int)$c['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider la conversion.');if((int)$c['current_heads']<(int)$c['input_heads'])throw new RuntimeException('Effectif vivant insuffisant.');$after=(int)$c['current_heads']-(int)$c['input_heads'];$this->query('UPDATE livestock_batches SET current_heads=:heads,status=IF(:heads2>0,status,\'completed\') WHERE id=:id',['heads'=>$after,'heads2'=>$after,'id'=>$c['batch_id']]);$this->headMove($c['batch_id'],$c['conversion_type']==='slaughter'?'slaughter':'transfer_out',$c['input_heads'],$c['current_heads'],$after,'livestock_conversions',$id,$u);$this->query("INSERT INTO livestock_weight_stocks(site_id,batch_id,conversion_id,quantity_kg,reserved_kg,status) VALUES(:site,:batch,:conversion,:qty,0,'available')",['site'=>$c['site_id'],'batch'=>$c['batch_id'],'conversion'=>$id,'qty'=>$c['net_weight_kg']]);$stock=(int)$this->db->lastInsertId();$this->weightMove($stock,'conversion_in',$c['net_weight_kg'],0,$c['net_weight_kg'],0,0,'livestock_conversions',$id,$u);$this->query("UPDATE livestock_conversions SET status='validated',validated_by=:user,validated_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->logActivity('validate_livestock_conversion','livestock','livestock_conversions',$id,'Conversion formelle des têtes vivantes en kilogrammes.',null,['stock_id'=>$stock],$u);$this->db->commit();return$stock;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createTransfer(array$d,array$u){$site=$this->farm();$dest=$this->siteId('BOUCH');$unit=$d['source_unit'];$batch=$this->row('SELECT * FROM livestock_batches WHERE id=? AND site_id=? AND status=\'active\'',[$d['batch_id'],$site]);if(!$batch)throw new RuntimeException('Lot source invalide.');$heads=null;$kg=null;$weight=null;if($unit==='head'){$heads=(int)$d['quantity_heads'];if($heads<=0||$heads>(int)$batch['current_heads'])throw new RuntimeException('Effectif insuffisant.');}elseif($unit==='kg'){$weight=$this->row("SELECT * FROM livestock_weight_stocks WHERE id=? AND batch_id=? AND status='available'",[$d['weight_stock_id'],$batch['id']]);$kg=(float)$d['quantity_kg'];if(!$weight||$kg<=0||$kg>(float)$weight['quantity_kg'])throw new RuntimeException('Stock pesé insuffisant.');}else throw new RuntimeException('Unité de transfert invalide.');$this->db->beginTransaction();try{$n='BTR-ELV-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO livestock_transfers(batch_id,weight_stock_id,source_site_id,destination_site_id,transfer_number,source_unit,quantity_heads,quantity_kg,status,truck_plate,driver_name,created_by) VALUES(:batch,:weight,:source,:dest,:number,:unit,:heads,:kg,'draft',:truck,:driver,:user)",['batch'=>$batch['id'],'weight'=>$weight['id']??null,'source'=>$site,'dest'=>$dest,'number'=>$n,'unit'=>$unit,'heads'=>$heads,'kg'=>$kg,'truck'=>strtoupper(trim($d['truck_plate'])),'driver'=>trim($d['driver_name']),'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BTR',$site,'livestock_transfers',$id,'draft',date('Y-m-d H:i:s'),$u);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveTransfer($id,array$u){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM livestock_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='draft')throw new RuntimeException('BTR non validable.');if((int)$t['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider le BTR.');Auth::requireSiteAccess($t['source_site_id']);if($t['source_unit']==='kg'){$s=$this->row('SELECT * FROM livestock_weight_stocks WHERE id=? FOR UPDATE',[$t['weight_stock_id']]);$avail=(float)$s['quantity_kg']-(float)$s['reserved_kg'];if($avail<(float)$t['quantity_kg'])throw new RuntimeException('Kilogrammes disponibles insuffisants.');$after=(float)$s['reserved_kg']+(float)$t['quantity_kg'];$this->query("UPDATE livestock_weight_stocks SET reserved_kg=:q,status='reserved' WHERE id=:id",['q'=>$after,'id'=>$s['id']]);$this->weightMove($s['id'],'reserve',$t['quantity_kg'],$s['quantity_kg'],$s['quantity_kg'],$s['reserved_kg'],$after,'livestock_transfers',$id,$u);}$this->query("UPDATE livestock_transfers SET status='approved',approved_by=:user WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->approveDoc($id,$u);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function dispatchTransfer($id,array$u){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM livestock_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='approved')throw new RuntimeException('BTR non expédiable ou déjà expédié.');Auth::requireSiteAccess($t['source_site_id']);if($t['source_unit']==='head'){$b=$this->row('SELECT * FROM livestock_batches WHERE id=? FOR UPDATE',[$t['batch_id']]);if((int)$b['current_heads']<(int)$t['quantity_heads'])throw new RuntimeException('Effectif insuffisant.');$after=(int)$b['current_heads']-(int)$t['quantity_heads'];$this->query('UPDATE livestock_batches SET current_heads=:q WHERE id=:id',['q'=>$after,'id'=>$b['id']]);$this->headMove($b['id'],'transfer_out',$t['quantity_heads'],$b['current_heads'],$after,'livestock_transfers',$id,$u);}else{$s=$this->row('SELECT * FROM livestock_weight_stocks WHERE id=? FOR UPDATE',[$t['weight_stock_id']]);$q=(float)$t['quantity_kg'];if((float)$s['quantity_kg']<$q||(float)$s['reserved_kg']<$q)throw new RuntimeException('Stock pesé réservé incohérent.');$after=(float)$s['quantity_kg']-$q;$reserved=(float)$s['reserved_kg']-$q;$this->query("UPDATE livestock_weight_stocks SET quantity_kg=:q,reserved_kg=:r,status=IF(:q2>0,'available','in_transit') WHERE id=:id",['q'=>$after,'r'=>$reserved,'q2'=>$after,'id'=>$s['id']]);$this->weightMove($s['id'],'transfer_out',$q,$s['quantity_kg'],$after,$s['reserved_kg'],$reserved,'livestock_transfers',$id,$u);}$this->query("UPDATE livestock_transfers SET status='in_transit',dispatched_by=:user,dispatched_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->logActivity('dispatch_livestock_transfer','livestock','livestock_transfers',$id,'BTR vers la boucherie expédié avec lot d’origine.',null,$t,$u);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function metrics($batchId){$b=$this->batch($batchId,true);$days=max(1,(strtotime(date('Y-m-d'))-strtotime($b['started_at']))/86400);$gmq=$b['initial_average_weight_kg']!==null&&$b['current_average_weight_kg']!==null?(((float)$b['current_average_weight_kg']-(float)$b['initial_average_weight_kg'])*1000/$days):null;$fishYield=$b['category']==='fish'&&$b['area_m2']>0?(float)$this->query("SELECT COALESCE(SUM(net_weight_kg),0) FROM fish_catches WHERE batch_id=:id AND status='validated'",['id'=>$b['id']])->fetchColumn()/(float)$b['area_m2']:null;return['gmq_g_day'=>$gmq,'fish_yield_kg_m2'=>$fishYield];}
 private function batch($id,$details=false){$sql=$details?"SELECT b.*,sp.category,f.area_m2 FROM livestock_batches b JOIN livestock_species sp ON sp.id=b.species_id JOIN livestock_facilities f ON f.id=b.facility_id WHERE b.id=? AND b.deleted_at IS NULL":"SELECT * FROM livestock_batches WHERE id=? AND deleted_at IS NULL";$b=$this->row($sql,[$id]);if(!$b)throw new RuntimeException('Lot introuvable.');Auth::requireSiteAccess($b['site_id']);return$b;}private function farm(){$s=Auth::requireCurrentSite();$c=$this->query('SELECT code FROM sites WHERE id=:id',['id'=>$s])->fetchColumn();if(!in_array($c,['FARM-MUT','FARM-DIK'],true))throw new RuntimeException('Sélectionnez MUTALA ou DIKAPA.');return$s;}private function siteId($c){return(int)$this->query('SELECT id FROM sites WHERE code=:c',['c'=>$c])->fetchColumn();}private function scoped($sql,$column){$p=[];$s=Auth::siteClause($column,$p);return$this->query($sql.$s.' ORDER BY name',$p)->fetchAll();}
 private function headMove($b,$t,$q,$before,$after,$rt,$rid,$u){$this->query('INSERT INTO livestock_head_movements(batch_id,movement_type,quantity_heads,heads_before,heads_after,reference_type,reference_id,movement_at,created_by) VALUES(:b,:t,:q,:before,:after,:rt,:rid,NOW(),:u)',['b'=>$b,'t'=>$t,'q'=>$q,'before'=>$before,'after'=>$after,'rt'=>$rt,'rid'=>$rid,'u'=>$u['id']]);}private function weightMove($s,$t,$q,$before,$after,$rb,$ra,$rt,$rid,$u){$this->query('INSERT INTO livestock_weight_movements(stock_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reserved_before_kg,reserved_after_kg,reference_type,reference_id,created_by) VALUES(:s,:t,:q,:b,:a,:rb,:ra,:rt,:rid,:u)',['s'=>$s,'t'=>$t,'q'=>$q,'b'=>$before,'a'=>$after,'rb'=>$rb,'ra'=>$ra,'rt'=>$rt,'rid'=>$rid,'u'=>$u['id']]);}private function approveDoc($id,$u){$d=$this->row("SELECT d.* FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code='BTR' AND d.entity_type='livestock_transfers' AND d.entity_id=? FOR UPDATE",[$id]);if($d){$this->query("UPDATE documents SET status='approved',validated_by=:u,validated_at=NOW() WHERE id=:id",['u'=>$u['id'],'id'=>$d['id']]);$this->query("INSERT INTO document_status_history(document_id,old_status,new_status,changed_by,reason) VALUES(:d,:old,'approved',:u,'Validation BTR élevage')",['d'=>$d['id'],'old'=>$d['status'],'u'=>$u['id']]);}}private function row($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetch();}
}
